#!/bin/bash
# Generate Kubernetes ConfigMap with Atlas schema and migrations

set -e

echo "🔧 Generating Atlas ConfigMap for Kubernetes..."

# Create temporary directory for building configmap
TEMP_DIR=$(mktemp -d)
trap "rm -rf $TEMP_DIR" EXIT

# Copy schema files
cp -r schema "$TEMP_DIR/"
cp -r atlas-migrations "$TEMP_DIR/"
cp atlas.hcl "$TEMP_DIR/"

# Generate ConfigMap YAML with embedded files
cat > k8s/atlas-configmap.yaml << EOF
# Atlas Configuration and Schema Files
# Auto-generated by scripts/generate-k8s-configmap.sh
apiVersion: v1
kind: ConfigMap
metadata:
  name: bonsai-atlas-config
  namespace: default
  labels:
    app: bonsai
    component: migration
data:
  atlas.hcl: |
$(sed 's/^/    /' atlas.hcl)

  # Schema files
$(find schema -name "*.hcl" -type f | while read file; do
  echo "  $(basename "$file"): |"
  sed 's/^/    /' "$file"
  echo ""
done)

  # Migration files
$(find atlas-migrations -name "*.sql" -type f | sort | while read file; do
  echo "  $(basename "$file"): |"
  sed 's/^/    /' "$file"
  echo ""
done)

  atlas.sum: |
$(sed 's/^/    /' atlas-migrations/atlas.sum)
EOF

echo "ConfigMap generated at k8s/atlas-configmap.yaml"

# Validate YAML syntax
if command -v yq >/dev/null 2>&1; then
    yq eval . k8s/atlas-configmap.yaml > /dev/null
    echo "YAML syntax validation passed"
else
    echo "Install yq for YAML validation: brew install yq"
fi

echo "🚀 Apply with: kubectl apply -f k8s/atlas-configmap.yaml"